package org.apache.commons.compress.utils;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ArchiveUtils_sanitize_TriageGen2Test {



    @Test
    public void testSanitize_ISOControlCharacters() {
        // Tests control characters (e.g., \n, \r, \t, \u0000)
        // Character.isISOControl will return true, resulting in '?'
        String input = "A\nB\rC\tD\u0000E";
        String expected = "A?B?C?D?E";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }










}

