import static org.junit.Assert.assertEquals;

public class ArchiveUtils_sanitize_TriageGen2Test {





    @Test
    public void testSanitize_SpecialsBlock() {
        // Tests characters in the SPECIALS Unicode block
        // Character.UnicodeBlock.of(c) == SPECIALS results in '?'
        // Examples: \u200B (Zero Width Space), \u2060 (Word Joiner)
        String input = "A\u200BB";
        String expected = "A?B";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }








}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ArchiveUtils_sanitize_TriageGen2Test {







    @Test
    public void testSanitize_NullUnicodeBlock() {
        // Tests cases where Character.UnicodeBlock.of(c) returns null
        // This can happen with certain unassigned or invalid characters 
        // that are not ISO control characters.
        // \uFFFF is often used in tests for such scenarios.
        String input = "A\uFFFFB";
        String expected = "A?B";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }






}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ArchiveUtils_sanitize_TriageGen2Test {









    @Test
    public void testSanitize_MixedContent() {
        // Combines normal, control, and special characters to maximize branch coverage
        // 1. Normal: 'z'
        // 2. ISO Control: '\u0007' (Bell)
        // 3. Specials: '\u200B'
        // 4. Null Block: '\uFFFF'
        String input = "z\u0007\u200B\uFFFFz";
        String expected = "z???z";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }




}

